     1	/**
     2	 * Bestsellers Update Utility Functions
     3	 * Uses DynamoDB atomic counter to update bestseller rankings
     4	 */
     5	
     6	const { docClient } = require('./dynamodb');
     7	const { dynamodb: dynamodbConfig } = require('../config');
     8	
     9	/**
    10	 * Update Bestseller List
    11	 * @param {string} bookId - Book ID
    12	 * @param {number} quantity - Quantity sold
    13	 * @returns {Promise<boolean>} Whether update was successful
    14	 */
    15	async function updateBestSeller(bookId, quantity) {
    16	  try {
    17	    const params = {
    18	      TableName: dynamodbConfig.bestsellersTable,
    19	      Key: { bookId: bookId },
    20	      UpdateExpression: 'ADD salesCount :qty',
    21	      ExpressionAttributeValues: {
    22	        ':qty': quantity
    23	      }
    24	    };
    25	
    26	    await docClient.update(params).promise();
    27	    console.log(`Updated bestseller: bookId=${bookId}, quantity=${quantity}`);
    28	    return true;
    29	  } catch (error) {
    30	    console.error('Failed to update bestseller:', error);
    31	    return false;
    32	  }
    33	}
    34	
    35	/**
    36	 * Batch Update Bestsellers
    37	 * @param {Array} books - Array of books, each element containing {bookId, quantity}
    38	 * @returns {Promise<Object>} Update result statistics
    39	 */
    40	async function updateBestSellers(books) {
    41	  if (!books || books.length === 0) {
    42	    return { success: 0, failed: 0 };
    43	  }
    44	
    45	  let success = 0;
    46	  let failed = 0;
    47	
    48	  for (const book of books) {
    49	    const result = await updateBestSeller(book.bookId, book.quantity);
    50	    if (result) {
    51	      success++;
    52	    } else {
    53	      failed++;
    54	    }
    55	  }
    56	
    57	  return { success, failed };
    58	}
    59	
    60	module.exports = {
    61	  updateBestSeller,
    62	  updateBestSellers
    63	};

1	/**
     2	 * Orders Related Routes
     3	 * Handles order query and creation (checkout) operations
     4	 */
     5	
     6	const express = require('express');
     7	const router = express.Router();
     8	const { docClient } = require('../utils/dynamodb');
     9	const { dynamodb } = require('../config');
    10	const authMiddleware = require('../middleware/auth');
    11	const { v4: uuidv4 } = require('uuid');
    12	const { updateBestSellers } = require('../utils/bestsellers');
    13	
    14	/**
    15	 * GET /orders
    16	 * List all orders for current user
    17	 */
    18	router.get('/', async (req, res, next) => {
    19	  try {
    20	    const params = {
    21	      TableName: dynamodb.ordersTable,
    22	      KeyConditionExpression: 'customerId = :customerId',
    23	      ExpressionAttributeValues: {
    24	        ':customerId': req.customerId
    25	      }
    26	    };
    27	
    28	    const data = await docClient.query(params).promise();
    29	    res.json(data.Items);
    30	  } catch (error) {
    31	    console.error('Error in GET /orders:', error);
    32	    next(error);
    33	  }
    34	});
    35	
    36	/**
    37	 * POST /orders
    38	 * Create new order (checkout process)
    39	 * Body: { books: [{ bookId, price, quantity }, ...] }
    40	 * 
    41	 * This operation will:
    42	 * 1. Create new order record
    43	 * 2. Clear checked out items from cart
    44	 */
    45	router.post('/', async (req, res, next) => {
    46	  try {
    47	    const { books } = req.body;
    48	
    49	    if (!books || !Array.isArray(books) || books.length === 0) {
    50	      return res.status(400).json({ 
    51	        error: 'Missing or invalid books array' 
    52	      });
    53	    }
    54	
    55	    // Generate order ID
    56	    const orderId = uuidv4();
    57	
    58	    // 1. Create order
    59	    const orderParams = {
    60	      TableName: dynamodb.ordersTable,
    61	      Item: {
    62	        customerId: req.customerId,
    63	        orderId: orderId,
    64	        orderDate: Date.now(),
    65	        books: books
    66	      }
    67	    };
    68	
    69	    await docClient.put(orderParams).promise();
    70	
    71	    // 2. Remove checked out items from cart
    72	    const deletePromises = books.map(book => {
    73	      const deleteParams = {
    74	        TableName: dynamodb.cartTable,
    75	        Key: {
    76	          customerId: req.customerId,
    77	          bookId: book.bookId
    78	        }
    79	      };
    80	      return docClient.delete(deleteParams).promise();
    81	    });
    82	
    83	    await Promise.all(deletePromises);
    84	
    85	    // 3. Sync update bestsellers (executed asynchronously, not blocking response)
    86	    // Update logic runs in background
    87	    updateBestSellers(books).then(result => {
    88	      if (result.success > 0) {
    89	        console.log(`Bestseller updated: ${result.success} books`);
    90	      }
    91	      if (result.failed > 0) {
    92	        console.warn(`Bestseller update failed for ${result.failed} books`);
    93	      }
    94	    }).catch(error => {
    95	      // Bestseller update failure should not affect order creation
    96	      console.error('Error updating bestsellers:', error);
    97	    });
    98	
    99	    res.json({ 
   100	      message: 'Order created successfully',
   101	      orderId: orderId
   102	    });
   103	  } catch (error) {
   104	    console.error('Error in POST /orders:', error);
   105	    next(error);
   106	  }
   107	});
   108	
   109	module.exports = router;

1	/**
     2	 * Search Routes
     3	 * Provides full-text search functionality using DynamoDB scan
     4	 */
     5	
     6	const express = require('express');
     7	const router = express.Router();
     8	const { docClient } = require('../utils/dynamodb');
     9	const { dynamodb: dynamodbConfig } = require('../config');
    10	
    11	/**
    12	 * GET /search?q=keyword
    13	 * Search books (by name, author, category)
    14	 * Query params: q - Search keyword
    15	 */
    16	router.get('/', async (req, res, next) => {
    17	  try {
    18	    const query = req.query.q;
    19	
    20	    if (!query) {
    21	      return res.status(400).json({
    22	        error: 'Missing required query parameter: q'
    23	      });
    24	    }
    25	
    26	    const params = {
    27	      TableName: dynamodbConfig.booksTable
    28	    };
    29	
    30	    const data = await docClient.scan(params).promise();
    31	
    32	    const lowerQuery = query.toLowerCase();
    33	    const results = (data.Items || []).filter(item => {
    34	      return (
    35	        (item.name && item.name.toLowerCase().includes(lowerQuery)) ||
    36	        (item.author && item.author.toLowerCase().includes(lowerQuery)) ||
    37	        (item.category && item.category.toLowerCase().includes(lowerQuery))
    38	      );
    39	    });
    40	
    41	    res.json({
    42	      total: results.length,
    43	      hits: results.map(item => ({
    44	        _source: item
    45	      }))
    46	    });
    47	  } catch (error) {
    48	    console.error('Error in GET /search:', error);
    49	    next(error);
    50	  }
    51	});
    52	
    53	module.exports = router;

