# -*- coding: utf-8 -*-
"""Offline provenance pre-check for the generated field values (mirrors m2s-mcp-server/provenance.py rules)."""
import json, os, glob

MONO = r"D:\Emma\MyLab\Mono2SLs\Mono2Sls-artifacts\mono_benchmark\bookstore"
OUT = os.path.join(os.environ.get("TEMP", r"C:\Users\36029\AppData\Local\Temp"), "f2", "vals")
cache = {}


def lines(rel):
    if rel not in cache:
        p = os.path.join(MONO, rel.replace("bookstore/", "").replace("/", os.sep))
        try:
            cache[rel] = open(p, encoding="utf-8").read().splitlines()
        except Exception as e:
            cache[rel] = None
    return cache[rel]


bad = 0
for f in sorted(glob.glob(os.path.join(OUT, "*.json"))):
    v = json.load(open(f, encoding="utf-8"))
    items = v if isinstance(v, list) else [i for loc in ("path_params", "query", "body", "headers") for i in (v.get(loc) or [])]
    def walk(it):
        global bad
        if isinstance(it, dict):
            for k, val in it.items():
                if k == "source" and isinstance(val, list):
                    for s in val:
                        if set(s) != {"file", "line", "symbol"}:
                            print("KEYS", os.path.basename(f), s); bad += 1
                        ls = lines(s["file"])
                        if ls is None:
                            print("MISSING FILE", os.path.basename(f), s["file"]); bad += 1; continue
                        ln = s["line"]
                        if not (1 <= ln <= len(ls)):
                            print("LINE RANGE", os.path.basename(f), s); bad += 1; continue
                        window = "\n".join(ls[max(0, ln - 3):min(len(ls), ln + 2)])
                        if s["symbol"] not in window:
                            print("SYMBOL", os.path.basename(f), json.dumps(s, ensure_ascii=False)); bad += 1
                        if len(s["symbol"]) > 120:
                            print("SYMBOL LONG", os.path.basename(f), s["symbol"]); bad += 1
                else:
                    walk(val)
        elif isinstance(it, list):
            for x in it:
                walk(x)
    walk(v)
print("BAD =", bad)

